('70536378-321f-5472-a1c1-f55a2dbfadbc','f748060f-ec82-557f-bfc3-1b6635fa1e1a',1,null,null,'spoken & written','to eat lunch',null,null,'برای خوردن ناهار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I will be lunching with a client.","translation":"من با یک مشتری ناهار خواهم خورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001739592.mp3"},{"sentence":"I lunched on bread and olives.","translation":"ناهار نان و زیتون خوردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001739595.mp3"},{"sentence":"We lunched at Maxim’s.","translation":"ناهار را در ماکسیم خوردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001739598.mp3"}]'::jsonb,3),
('6ead37fe-b453-5304-831e-e117fb1cc4d9','fafe0c81-a18f-5724-9eef-5efdac7fd8ac',1,null,null,'formal','used to address a woman in a polite way, especially a customer in a shop',null,null,'بانو، خانم (خطاب محترمانه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Are you being served, Madam?","translation":"شما در خدمت هستید خانم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000171664.mp3"}]'::jsonb,1),
